import numpy as np
from scipy import stats

MAX_DRIVERS = 2

def design(feats):
    # Get t-statistics for all features
    t_stats = []
    for i, fid in enumerate(feats.ids):
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, _ = stats.ttest_ind(y0, y1)
            t_stats.append((abs(t_stat), fid))
        else:
            t_stats.append((0, fid))

    # Sort by strength and take top 2
    t_stats.sort(reverse=True)
    drivers = [fid for _, fid in t_stats[:MAX_DRIVERS]]

    # Remove any drivers that are highly correlated with each other
    if len(drivers) >= 2:
        idx1 = feats.column(drivers[0])
        idx2 = feats.column(drivers[1])
        r = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]
        if abs(r) >= 0.6:
            # Keep only the stronger one
            if t_stats[0][0] >= t_stats[1][0]:
                drivers = [drivers[0]]
            else:
                drivers = [drivers[1]]

    # Return minimal design with just the drivers
    return Design(
        drivers=tuple(drivers),
        columns=tuple(drivers),
        products=(),
        loadings={}
    )

